fragmentVersions.css:
.rays-breakfast {
	background: radial-gradient(circle at 15% 20%, #3a2416 0%, #1a120d 55%, #0f0b08 100%);
	color: #f5ede6;
	font-family: Georgia, serif;
	padding: 32px 32px;
}

.rays-breakfast__inner {
	align-items: center;
	display: flex;
	gap: 32px;
	margin: 0 auto;
	max-width: 1040px;
}

.rays-breakfast__icon {
	flex: 0 0 180px;
	height: 180px;
	width: 180px;
}

.rays-breakfast__eyebrow {
	color: var(--rays-accent);
	font-family: system-ui, sans-serif;
	font-size: 22px;
	font-weight: 700;
	letter-spacing: 0.16em;
	margin: 0 0 8px;
	text-transform: uppercase;
}

.rays-breakfast__title {
	color: #fff8f1;
	font-size: 50px;
	line-height: 1.05;
	margin: 0 0 14px;
}

.rays-breakfast__hours {
	display: flex;
	flex-wrap: wrap;
	gap: 12px 40px;
	margin: 0 0 18px;
}

.rays-breakfast__slot {
	border-left: 4px solid var(--rays-accent);
	padding-left: 14px;
}

.rays-breakfast__days {
	color: #d9c8b8;
	font-family: system-ui, sans-serif;
	font-size: 26px;
	line-height: 1.2;
	margin: 0;
}

.rays-breakfast__time {
	color: #fff8f1;
	font-size: 32px;
	font-weight: 700;
	line-height: 1.2;
	margin: 0;
}

.rays-breakfast__cta {
	background: var(--rays-accent);
	border-radius: 999px;
	color: #120d09;
	display: inline-block;
	font-family: system-ui, sans-serif;
	font-size: 24px;
	font-weight: 700;
	padding: 12px 32px;
}

@media (max-width: 640px) {
	.rays-breakfast__inner {
		flex-direction: column;
		text-align: center;
	}

	.rays-breakfast__hours {
		justify-content: center;
	}
}
